def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval - add it to merged list
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and calculate in-degrees
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected")
        graph[source].append(dest)
        in_degree[dest] += 1

    # Find all nodes with zero in-degree
    queue = [node for node in nodes if in_degree[node] == 0]
    import heapq
    heapq.heapify(queue)

    result = []

    while queue:
        # Get the lexicographically smallest node
        current = heapq.heappop(queue)
        result.append(current)

        # Process neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(queue, neighbor)

    # Check for cycles
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("Limit must be positive")

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Weights must be positive and not exceed the limit")

        if current_weight + weight > limit:
            if current_batch:
                batches.append(current_batch)
            current_batch = []
            current_weight = 0

        current_batch.append(name)
        current_weight += weight

    if current_batch:
        batches.append(current_batch)

    return batches

def parse_sse(chunks):
    data_lines = []
    result = []
    buffer = b""
    line_buffer = ""

    for chunk in chunks:
        buffer += chunk

        # Handle UTF-8 decoding with error handling
        try:
            decoded = buffer.decode('utf-8')
        except UnicodeDecodeError:
            # If we can't decode yet, continue buffering
            continue

        lines = decoded.splitlines(True)  # Keep line endings

        # If the last element doesn't end with a line ending, it's incomplete
        if not decoded.endswith(('\n', '\r\n')):
            line_buffer += lines[-1]
            lines = lines[:-1]
        else:
            line_buffer = ""

        for line in lines:
            if line.endswith('\r\n'):
                line = line[:-2]
            elif line.endswith('\n'):
                line = line[:-1]

            if not line and line_buffer == "":
                # Blank line - dispatch event
                if data_lines:  # Only if we have data
                    result.append('\n'.join(data_lines))
                    data_lines = []
                continue

            if line.startswith('data:'):
                data_line = line[5:].lstrip()
                data_lines.append(data_line)
            elif line == "[DONE]":
                # Stop processing on [DONE]
                return result

    # Process final event if complete
    if data_lines:
        result.append('\n'.join(data_lines))

    return result

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Negative arguments not allowed")

    if attempt >= 10**9:
        # Handle large attempt values without overflow
        if base == 0 or cap == 0:
            return float(cap)
        # For very large attempts, 2^attempt will be huge
        # We just need to check if base * 2^attempt exceeds cap
        # If cap is finite and base > 0, then base * 2^attempt will eventually exceed cap
        # But we can't compute 2^10^9, so we assume it's large enough
        return float(cap)

    # For normal cases, compute 2^attempt directly
    try:
        delay = base * (2 ** attempt)
        return min(float(cap), delay)
    except OverflowError:
        # Handle overflow by returning cap
        return float(cap)

def fifo_admit(active, queued, budget, slots):
    # Check if any queued reservation exceeds the whole budget
    for reservation in queued:
        if reservation > budget:
            raise ValueError("Queued reservation exceeds budget")

    # Initialize results
    admitted = active[:]
    remaining = []

    # Track current usage
    token_usage = sum(active)
    slot_usage = len(active)

    # Process queued requests in FIFO order
    for reservation in queued:
        if slot_usage < slots and token_usage + reservation <= budget:
            admitted.append(reservation)
            token_usage += reservation
            slot_usage += 1
        else:
            remaining.append(reservation)

    return (admitted, remaining)
